package itda.medicalsupport.controller;
import itda.common.dto.ApiResponse; import itda.common.security.CurrentUser; import itda.medicalsupport.dto.MedicalSupportIngestionResponse; import itda.medicalsupport.dto.MedicalSupportRejectRequest; import itda.medicalsupport.service.*; import jakarta.validation.Valid; import java.util.*; import lombok.RequiredArgsConstructor; import org.springframework.http.ResponseEntity; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/admin/medical-support") @RequiredArgsConstructor public class AdminMedicalSupportController {private final MedicalSupportReviewService review; private final MedicalSupportIngestionService ingestion; @PostMapping("/sources/{sourceKey}/ingestions") public ResponseEntity<ApiResponse<MedicalSupportIngestionResponse>> ingest(@PathVariable String sourceKey){MedicalSupportIngestionResult result=ingestion.ingestResult(sourceKey);String message=result.created()?"공식 원문을 수집했습니다. 검토 대기 상태입니다.":"기존 수집 이력을 재사용했습니다.";return ResponseEntity.ok(ApiResponse.ok(MedicalSupportIngestionResponse.from(result),message));} @PostMapping("/revisions/{revisionId}/verify") public ResponseEntity<ApiResponse<Long>> verify(@AuthenticationPrincipal CurrentUser user,@PathVariable long revisionId){return ResponseEntity.ok(ApiResponse.ok(review.verify(user.id(),revisionId).getId(),"수집 이력을 검증했습니다."));} @PostMapping("/revisions/{revisionId}/reject") public ResponseEntity<ApiResponse<Long>> reject(@AuthenticationPrincipal CurrentUser user,@PathVariable long revisionId,@Valid @RequestBody MedicalSupportRejectRequest request){return ResponseEntity.ok(ApiResponse.ok(review.reject(user.id(),revisionId,request.reason()).getId(),"수집 이력을 반려했습니다."));}}
